using HRM.Models;
using HRM.Models.WorkPlanning;
using HRM.WorkPlanning.Abstractions;
using Microsoft.EntityFrameworkCore;
namespace HRM.WorkPlanning.Services;
public sealed class WorkforceAttendanceSessionService(IDbContextFactory<HrmTeContext> factory,IWorkTimeLedgerService ledger):IWorkforceAttendanceSessionService
{public async Task<long> EvaluateAsync(EvaluateWorkforceSession e,CancellationToken ct=default){if(e.ActualMinutes<0||e.CreditedMinutes<0||e.Status is not("Completed" or "PendingReview"))throw new InvalidOperationException("Invalid attendance session evaluation.");await using var db=await factory.CreateDbContextAsync(ct);var segment=await db.WorkPlanSegments.Include(x=>x.WorkPlan).SingleOrDefaultAsync(x=>x.WorkPlanSegmentId==e.WorkPlanSegmentId,ct)??throw new InvalidOperationException("Work-plan segment not found.");var version=(await db.WorkforceAttendanceSessions.Where(x=>x.WorkPlanSegmentId==e.WorkPlanSegmentId).MaxAsync(x=>(int?)x.EvaluationVersion,ct)??0)+1;var row=new WorkforceAttendanceSession{WorkPlanSegmentId=e.WorkPlanSegmentId,DutyAssignmentId=e.DutyAssignmentId,Status=e.Status,EvaluationStrategy=e.Strategy,ActualMinutes=e.ActualMinutes,CreditedMinutes=e.CreditedMinutes,MatchReason=e.MatchReason,EvaluationVersion=version,EvaluatedAtUtc=DateTime.UtcNow,OperationLogId=e.OperationLogId};db.WorkforceAttendanceSessions.Add(row);await db.SaveChangesAsync(ct);if(e.Status=="Completed")await ledger.RecordAsync(new(segment.WorkPlan.OrganisationBusinessEntityId,segment.WorkPlan.IndividualId,segment.WorkPlan.JobId,segment.StartDateTime,segment.EndDateTime,"Attendance",e.ActualMinutes,e.CreditedMinutes,$"WS_SESSION:{row.Id}",e.OperationLogId,e.WorkPlanSegmentId,e.DutyAssignmentId),ct);return row.Id;}}
